import Foundation
import CSQLite

/// Bound value for a prepared statement parameter.
public enum SQLValue: Sendable, Hashable {
    case null
    case integer(Int64)
    case real(Double)
    case text(String)
    case blob([UInt8])
}

/// A single row, addressable by column name.
public struct Row: Sendable {
    private let values: [String: SQLValue]
    init(_ values: [String: SQLValue]) { self.values = values }

    public subscript(column: String) -> SQLValue? { values[column] }

    public func int(_ column: String) -> Int64? {
        if case .integer(let v)? = values[column] { return v }
        return nil
    }
    public func double(_ column: String) -> Double? {
        switch values[column] {
        case .real(let v)?: return v
        case .integer(let v)?: return Double(v)
        default: return nil
        }
    }
    public func string(_ column: String) -> String? {
        if case .text(let v)? = values[column] { return v }
        return nil
    }
    public func isNull(_ column: String) -> Bool {
        if case .null? = values[column] { return true }
        return values[column] == nil
    }
}

private let SQLITE_TRANSIENT = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

/// A thin, non-generic wrapper over the SQLite C API.
///
/// Deliberately small. It is a seam, not an ORM: the schema lives in
/// migrations, and everything above this type works in plain SQL so that a
/// migration and a query read the same on Linux and on iOS.
/// Thread safety: the connection is opened with SQLITE_OPEN_FULLMUTEX, so
/// SQLite itself serialises concurrent use of the handle. That is what makes
/// the `@unchecked Sendable` claim true rather than convenient.
public final class Database: @unchecked Sendable {
    private var handle: OpaquePointer?
    /// Internal escape hatch for C APIs that need the raw connection.
    var rawHandle: OpaquePointer? { handle }
    public let path: String
    /// Held for the whole of `transaction`. Recursive, so the same thread can
    /// nest; another thread waits rather than joining the open transaction.
    private let transactionLock = NSRecursiveLock()

    public init(path: String) throws {
        self.path = path
        var h: OpaquePointer?
        let flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX
        let rc = sqlite3_open_v2(path, &h, flags, nil)
        guard rc == SQLITE_OK, let opened = h else {
            let err = SQLiteError.from(h, code: rc)
            if h != nil { sqlite3_close_v2(h) }
            throw err
        }
        self.handle = opened
        try execute("PRAGMA foreign_keys = ON;")
        try execute("PRAGMA journal_mode = WAL;")
        try execute("PRAGMA busy_timeout = 5000;")
    }

    public static func inMemory() throws -> Database { try Database(path: ":memory:") }

    deinit { if let handle { sqlite3_close_v2(handle) } }

    /// Runs one or more statements with no parameters and no result rows.
    public func execute(_ sql: String) throws {
        var errmsg: UnsafeMutablePointer<CChar>?
        let rc = sqlite3_exec(handle, sql, nil, nil, &errmsg)
        if rc != SQLITE_OK {
            let message = errmsg.map { String(cString: $0) } ?? "unknown sqlite error"
            if let errmsg { sqlite3_free(errmsg) }
            throw SQLiteError(code: rc, message: message, sql: sql)
        }
    }

    @discardableResult
    public func run(_ sql: String, _ parameters: [SQLValue] = []) throws -> Int {
        let stmt = try prepare(sql, parameters)
        defer { sqlite3_finalize(stmt) }
        let rc = sqlite3_step(stmt)
        guard rc == SQLITE_DONE || rc == SQLITE_ROW else {
            throw SQLiteError.from(handle, code: rc, sql: sql)
        }
        return Int(sqlite3_changes(handle))
    }

    public func query(_ sql: String, _ parameters: [SQLValue] = []) throws -> [Row] {
        let stmt = try prepare(sql, parameters)
        defer { sqlite3_finalize(stmt) }

        let columnCount = Int(sqlite3_column_count(stmt))
        var names: [String] = []
        names.reserveCapacity(columnCount)
        for i in 0..<columnCount {
            names.append(String(cString: sqlite3_column_name(stmt, Int32(i))))
        }

        var rows: [Row] = []
        while true {
            let rc = sqlite3_step(stmt)
            if rc == SQLITE_DONE { break }
            guard rc == SQLITE_ROW else { throw SQLiteError.from(handle, code: rc, sql: sql) }
            var values: [String: SQLValue] = [:]
            for i in 0..<columnCount {
                values[names[i]] = columnValue(stmt, Int32(i))
            }
            rows.append(Row(values))
        }
        return rows
    }

    private func columnValue(_ stmt: OpaquePointer?, _ index: Int32) -> SQLValue {
        switch sqlite3_column_type(stmt, index) {
        case SQLITE_INTEGER: return .integer(sqlite3_column_int64(stmt, index))
        case SQLITE_FLOAT:   return .real(sqlite3_column_double(stmt, index))
        case SQLITE_TEXT:
            guard let c = sqlite3_column_text(stmt, index) else { return .null }
            return .text(String(cString: c))
        case SQLITE_BLOB:
            let n = Int(sqlite3_column_bytes(stmt, index))
            guard n > 0, let p = sqlite3_column_blob(stmt, index) else { return .blob([]) }
            let buf = UnsafeRawBufferPointer(start: p, count: n)
            return .blob(Array(buf))
        default: return .null
        }
    }

    private func prepare(_ sql: String, _ parameters: [SQLValue]) throws -> OpaquePointer? {
        var stmt: OpaquePointer?
        let rc = sqlite3_prepare_v2(handle, sql, -1, &stmt, nil)
        guard rc == SQLITE_OK else { throw SQLiteError.from(handle, code: rc, sql: sql) }
        for (offset, value) in parameters.enumerated() {
            let i = Int32(offset + 1)
            let brc: Int32
            switch value {
            case .null:            brc = sqlite3_bind_null(stmt, i)
            case .integer(let v):  brc = sqlite3_bind_int64(stmt, i, v)
            case .real(let v):     brc = sqlite3_bind_double(stmt, i, v)
            case .text(let v):     brc = sqlite3_bind_text(stmt, i, v, -1, SQLITE_TRANSIENT)
            case .blob(let bytes):
                brc = bytes.isEmpty
                    ? sqlite3_bind_zeroblob(stmt, i, 0)
                    : bytes.withUnsafeBufferPointer {
                        sqlite3_bind_blob(stmt, i, $0.baseAddress, Int32(bytes.count), SQLITE_TRANSIENT)
                      }
            }
            guard brc == SQLITE_OK else {
                sqlite3_finalize(stmt)
                throw SQLiteError.from(handle, code: brc, sql: sql)
            }
        }
        return stmt
    }

    /// Runs `body` inside a transaction, rolling back on any thrown error.
    ///
    /// **Nests.** `BEGIN` inside an open transaction is an error in SQLite, so
    /// a call made while one is already running uses a SAVEPOINT instead: the
    /// inner scope rolls back on its own without discarding the outer one, and
    /// nothing commits until the outermost scope does. That is what lets a
    /// store compose two writes that each own their own consistency — a recipe
    /// and the values derived from it, or a whole source's rows — without
    /// either having to know whether it is the outer call.
    ///
    /// Whether a transaction is open is asked of SQLite rather than tracked
    /// here, so there is no Swift-side counter that can drift out of step with
    /// the connection. Savepoints of the same name are last-in-first-out, which
    /// is exactly how these scopes close.
    ///
    /// **Nesting is per thread, which the lock is what makes true.** SQLite
    /// reports an open transaction for the *connection*, not for the caller, so
    /// without the lock a second thread arriving mid-transaction would read
    /// "already open" and quietly attach its savepoint to work it has nothing
    /// to do with — two unrelated units of work committing or rolling back
    /// together. `SQLITE_OPEN_FULLMUTEX` serialises statements, not the spans
    /// between them, so it does not cover this. Holding the lock for the whole
    /// scope means another thread waits and then gets a genuine outer
    /// transaction of its own.
    public func transaction<T>(_ body: () throws -> T) throws -> T {
        transactionLock.lock()
        defer { transactionLock.unlock() }
        guard sqlite3_get_autocommit(handle) != 0 else { return try savepoint(body) }
        try execute("BEGIN IMMEDIATE;")
        do {
            let result = try body()
            try execute("COMMIT;")
            return result
        } catch {
            try? execute("ROLLBACK;")
            throw error
        }
    }

    private func savepoint<T>(_ body: () throws -> T) throws -> T {
        try execute("SAVEPOINT almanac_nested;")
        do {
            let result = try body()
            try execute("RELEASE almanac_nested;")
            return result
        } catch {
            // Rolling back to a savepoint does not release it, so both
            // statements are needed to leave the enclosing scope as it was.
            try? execute("ROLLBACK TO almanac_nested;")
            try? execute("RELEASE almanac_nested;")
            throw error
        }
    }

    public var userVersion: Int {
        get { (try? query("PRAGMA user_version;").first?.int("user_version")).flatMap { $0 }.map(Int.init) ?? 0 }
    }
}

import Foundation

public struct HealthApplyCounts: Sendable, Hashable {
    public let inserted: Int
    public let updated: Int
    public let deleted: Int
    public init(inserted: Int, updated: Int, deleted: Int) {
        self.inserted = inserted; self.updated = updated; self.deleted = deleted
    }
    public static let zero = HealthApplyCounts(inserted: 0, updated: 0, deleted: 0)
}

/// Writes a change set. **Must not open its own transaction** — the caller
/// owns it, because the rows and the cursor advance have to commit together.
public protocol HealthSampleWriting: Sendable {
    func apply(_ changeSet: HealthChangeSet, in db: Database) throws -> HealthApplyCounts
}

/// Persists samples for one `HealthDomain`. This slice wires up `.bodyMass`
/// only; the table and this type are domain-agnostic, but no other domain is
/// enabled, tested, or claimed to work.
public struct HealthSampleStore: HealthSampleWriting, TimelineProviding, @unchecked Sendable {
    public let domain: String
    public let healthDomain: HealthDomain
    public let sourceSystem: String
    private let db: Database
    private let clock: any Clock
    private let zone: ZoneContext

    public init(db: Database, healthDomain: HealthDomain = .bodyMass,
                sourceSystem: String = "healthkit",
                clock: any Clock = SystemClock(),
                zone: ZoneContext = ZoneContext(TimeZone.current)) {
        self.db = db
        self.healthDomain = healthDomain
        self.sourceSystem = sourceSystem
        self.domain = healthDomain.rawValue
        self.clock = clock
        self.zone = zone
    }

    private var nowText: String { ISO8601DateFormatter().string(from: clock.now) }
    private func iso(_ date: Date) -> String { ISO8601DateFormatter().string(from: date) }

    @discardableResult
    public func apply(_ changeSet: HealthChangeSet, in db: Database) throws -> HealthApplyCounts {
        var inserted = 0, updated = 0, deleted = 0

        for sample in changeSet.added where sample.domain == healthDomain {
            let existing = try db.query("""
                SELECT id FROM health_sample WHERE source_system = ? AND external_id = ?;
                """, [.text(sourceSystem), .text(sample.externalID)]).first?.string("id")
            // Identity is (source_system, external_id): the same string from a
            // different source is a different sample, never an update of this one.
            try db.run("""
            INSERT INTO health_sample
                (id, source_system, external_id, domain, start_at, end_at, value, unit,
                 source_name, recorded_at, recorded_tz_offset_minutes, deleted_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)
            ON CONFLICT(source_system, external_id) DO UPDATE SET
                start_at    = excluded.start_at,
                end_at      = excluded.end_at,
                value       = excluded.value,
                unit        = excluded.unit,
                source_name = excluded.source_name,
                recorded_at = excluded.recorded_at,
                deleted_at  = NULL;
            """, [
                .text(existing ?? UUID().uuidString), .text(sourceSystem),
                .text(sample.externalID), .text(sample.domain.rawValue),
                .text(iso(sample.start)), .text(iso(sample.end)),
                sample.value.map { SQLValue.real($0) } ?? .null,
                sample.unit.map { SQLValue.text($0) } ?? .null,
                sample.sourceName.map { SQLValue.text($0) } ?? .null,
                .text(nowText),
                zone.offsetMinutes.map { SQLValue.integer(Int64($0)) } ?? .null
            ])
            if existing == nil { inserted += 1 } else { updated += 1 }
        }

        // Soft delete. A source withdrawing a sample is a fact about the
        // source, not permission to erase what was already recorded.
        for externalID in changeSet.deletedExternalIDs {
            deleted += try db.run("""
                UPDATE health_sample SET deleted_at = ?
                WHERE source_system = ? AND external_id = ? AND deleted_at IS NULL;
                """, [.text(nowText), .text(sourceSystem), .text(externalID)])
        }

        return HealthApplyCounts(inserted: inserted, updated: updated, deleted: deleted)
    }

    public func liveSampleCount() throws -> Int {
        Int(try db.query("""
            SELECT COUNT(*) AS n FROM health_sample
            WHERE source_system = ? AND domain = ? AND deleted_at IS NULL;
            """, [.text(sourceSystem), .text(healthDomain.rawValue)])
            .first?.int("n") ?? 0)
    }

    public func isDeleted(externalID: String) throws -> Bool {
        guard let row = try db.query("""
            SELECT deleted_at FROM health_sample WHERE source_system = ? AND external_id = ?;
            """, [.text(sourceSystem), .text(externalID)]).first else { return false }
        return !row.isNull("deleted_at")
    }

    public func entries(from: String, to: String) throws -> [TimelineEntry] {
        guard let range = DateRange(from: from, to: to) else { return [] }
        // Normalised to UTC before it reaches SQL. `start_at` is stored as a
        // UTC `...Z` string, so comparing it lexically against a caller's
        // `+03:00` text would be wrong by three hours — and silently so.
        let bounds = range.utcTextBounds
        return try db.query("""
        SELECT id, external_id, start_at, value, unit, source_name
        FROM health_sample
        WHERE source_system = ? AND domain = ? AND deleted_at IS NULL
          AND start_at >= ? AND start_at < ?
        ORDER BY start_at;
        """, [.text(sourceSystem), .text(healthDomain.rawValue),
              .text(bounds.start), .text(bounds.end)])
        .compactMap { row in
            // Samples always carry a full instant, so their span is a point and
            // the fit is always `.definite`. Computed through the same API as
            // Laboratory so the two domains cannot drift apart on what a range
            // means.
            guard let id = row.string("id"), let start = row.string("start_at"),
                  let occurrence = PartialDateTime(storedText: start, precision: .instant,
                                                   zone: .unknown),
                  let fit = occurrence.fit(in: range) else { return nil }
            let value: ValuePresentation
            if let v = row.double("value") {
                value = .quantity(text: String(v), unit: row.string("unit"))
            } else {
                value = .missing(reason: LabMissingReason.notReportedBySource.rawValue)
            }
            return TimelineEntry(
                domain: domain, kind: "sample", recordTable: "health_sample", recordID: id,
                occurrence: occurrence, basis: .occurrence,
                title: healthDomain.rawValue, detail: row.string("source_name"),
                value: value, lifecycle: nil, rangeFit: fit)
        }
    }
}

import Foundation

public struct SyncOutcome: Sendable, Hashable {
    public let counts: HealthApplyCounts
    public let advancedTo: [UInt8]?
}

/// One incremental sync, with the property that matters: **the imported rows
/// and the cursor advance commit together.**
///
/// The read from the provider happens outside the transaction; only the write
/// is inside it. If the write throws, the transaction rolls back and the anchor
/// keeps its previous value, so the next run re-reads the same range. An anchor
/// that advanced past rows that were never persisted would skip them for good.
public struct HealthSyncService: Sendable {
    private let db: Database
    private let provider: any HealthProvider
    private let anchors: SyncAnchorStore
    private let writer: any HealthSampleWriting
    private let healthDomain: HealthDomain
    private let anchorKey: String

    public init(db: Database, provider: any HealthProvider, writer: any HealthSampleWriting,
                healthDomain: HealthDomain = .bodyMass, clock: any Clock = SystemClock(),
                anchorKey: String? = nil) {
        self.db = db
        self.provider = provider
        self.writer = writer
        self.healthDomain = healthDomain
        self.anchors = SyncAnchorStore(db: db, clock: clock)
        self.anchorKey = anchorKey ?? healthDomain.rawValue
    }

    public func currentAnchor() throws -> [UInt8]? {
        try anchors.load(anchorKey)?.token
    }

    @discardableResult
    public func syncOnce() async throws -> SyncOutcome {
        let previous = try anchors.load(anchorKey)?.token
        let changeSet = try await provider.changes(in: healthDomain, since: previous)
        do {
            return try db.transaction {
                let counts = try writer.apply(changeSet, in: db)
                try anchors.save(domain: anchorKey, token: changeSet.nextAnchor)
                return SyncOutcome(counts: counts, advancedTo: changeSet.nextAnchor)
            }
        } catch {
            // The rows and the advance both rolled back. Record why, without
            // clearing the last good anchor.
            try? anchors.recordFailure(domain: anchorKey, message: String(describing: error))
            throw error
        }
    }
}

