3	/// How a stored partial date relates to a query range.
4	///
5	/// The distinction exists because a coarse value denotes a *span*, not an
6	/// instant. "March 2019" is not the same claim as "1 March 2019, 00:00", and a
7	/// range query that treats it as the latter makes the record vanish from any
8	/// range that starts later in March. That is the failure this type prevents.
9	public enum RangeFit: String, Codable, Sendable, Hashable {
10	    /// Every instant the stored value could denote lies inside the range.
11	    case definite
12	    /// The span overlaps the range but also extends outside it, so the record
13	    /// *may* belong to the range. Returned and labelled, never dropped.
14	    case potential
15	}
16	
17	/// A half-open query range, built from ISO-8601 prefixes of any precision.
18	public struct DateRange: Sendable, Hashable {
19	    public let start: Date
20	    public let end: Date
21	
22	    /// `from` and `to` are ISO-8601 prefixes: "2019", "2019-03", "2019-03-15",
23	    /// or a full instant. Each is resolved to the first instant of its span.
24	    public init?(from: String, to: String) {
25	        guard let a = PartialDateTime(inferringPrecisionFrom: from)?.span?.start,
26	              let b = PartialDateTime(inferringPrecisionFrom: to)?.span?.start else { return nil }
27	        self.start = a
28	        self.end = b
29	    }
30	
31	    public init(start: Date, end: Date) {
32	        self.start = start
33	        self.end = end
34	    }
35	
36	    /// The bounds as canonical UTC ISO-8601 text.
37	    ///
38	    /// For SQL, where stored instants are UTC strings. Comparing a stored
39	    /// `...Z` value against a caller's `+03:00` text lexically is wrong by the
40	    /// size of the offset; normalising both to UTC first is the fix.
41	    public var utcTextBounds: (start: String, end: String) {
42	        (DateRange.utcFormatter.string(from: start), DateRange.utcFormatter.string(from: end))
43	    }
44	
45	    static let utcFormatter: ISO8601DateFormatter = {
46	        let f = ISO8601DateFormatter()
47	        f.formatOptions = [.withInternetDateTime]
48	        f.timeZone = TimeZone(secondsFromGMT: 0)
49	        return f
50	    }()
51	}
52	
53	extension PartialDateTime {
54	
55	    /// Builds a value from an ISO-8601 prefix, taking precision from its shape.
56	    public init?(inferringPrecisionFrom text: String) {
57	        guard let precision = PartialDateTime.inferPrecision(text) else { return nil }
58	        self.init(storedText: text, precision: precision)
59	    }
60	
61	    static func inferPrecision(_ s: String) -> TimePrecision? {
62	        let local = PartialDateTime.localText(s)
63	        switch local.count {
64	        case 0: return .unknown
65	        case 4: return .year
66	        case 7: return .month
67	        case 10: return .day
68	        case 13: return .hour
69	        case 16: return .minute
70	        case let n where n >= 19: return .instant
71	        default: return nil
72	        }
73	    }
74	
75	    /// The half-open span of instants this value could denote.
76	    ///
77	    /// Derived for querying only — **nothing here is written back to storage**,
78	    /// so a month-precision record stays `"2019-03"` on disk. This answers
79	    /// "which instants could that label cover", which is a different question
80	    /// from "what time did this happen", and the second is still unknown.
81	    ///
82	    /// Resolved in the record's own offset when it has one, otherwise in UTC.
83	    /// For a coarse value with no offset that means the span can be up to a day
84	    /// out at its edges, which is why such a record reports `.potential` rather
85	    /// than `.definite` near a boundary.
86	    public var span: (start: Date, end: Date)? {
87	        guard isKnown, Self.shapeMatches(text, precision) else { return nil }
88	
89	        if precision == .instant {
90	            let formatter = ISO8601DateFormatter()
91	            formatter.formatOptions = [.withInternetDateTime]
92	            let parsedText: String
93	            if Self.explicitOffset(text) != nil { parsedText = text.uppercased() }
94	            else {
95	                let offset = zone.offsetMinutes ?? 0
96	                let suffix = String(format: "%@%02d:%02d", offset < 0 ? "-" : "+", abs(offset) / 60, abs(offset) % 60)
