107	
108	        let characters = Array(text)
109	        func number(_ lower: Int, _ upper: Int) -> Int? {
110	            guard characters.count >= upper else { return nil }
111	            return Int(String(characters[lower..<upper]))
112	        }
113	
114	        guard let year = number(0, 4) else { return nil }
115	        var components = DateComponents()
116	        components.year = year
117	        components.month = 1; components.day = 1
118	        components.hour = 0; components.minute = 0; components.second = 0
119	
120	        var unit: Calendar.Component = .year
121	        if precision.rank >= TimePrecision.month.rank {
122	            guard let month = number(5, 7) else { return nil }
123	            components.month = month; unit = .month
124	        }
125	        if precision.rank >= TimePrecision.day.rank {
126	            guard let day = number(8, 10) else { return nil }
127	            components.day = day; unit = .day
128	        }
129	        if precision.rank >= TimePrecision.hour.rank {
130	            guard let hour = number(11, 13) else { return nil }
131	            components.hour = hour; unit = .hour
132	        }
133	        if precision.rank >= TimePrecision.minute.rank {
134	            guard let minute = number(14, 16) else { return nil }
135	            components.minute = minute; unit = .minute
136	        }
137	
138	        guard let start = calendar.date(from: components),
139	              let end = calendar.date(byAdding: unit, value: 1, to: start) else { return nil }
140	        return (start, end)
141	    }
142	
143	    private static let fractionalFormatter: ISO8601DateFormatter = {
144	        let f = ISO8601DateFormatter()
145	        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
146	        return f
147	    }()
148	
149	    /// `nil` when the value cannot belong to the range at all.
150	    ///
151	    /// A coarse value whose span merely *overlaps* the range comes back as
152	    /// `.potential` instead of being dropped, because dropping it would assert
153	    /// that it happened outside the range — which the record does not say.
154	    public func fit(in range: DateRange) -> RangeFit? {
155	        // With no offset the span was resolved in UTC, which is a convenience,
156	        // not a fact. The true instant can be up to 14 hours either side, so
157	        // the overlap test widens by that much — never wrongly excluding — and
158	        // the answer can never be `.definite`, because definite membership is
159	        // exactly the claim an unknown offset cannot support.
160	        guard let possible = possibleSpan else { return nil }
161	        if possible.end <= range.start || possible.start >= range.end { return nil }
162	        if hasKnownOffset && possible.start >= range.start && possible.end <= range.end { return .definite }
163	        return .potential
164	    }
165	
166	    /// Bounds of uncertainty, not invented occurrence times.
167	    var possibleSpan: (start: Date, end: Date)? {
168	        guard let span else { return nil }
169	        let margin = hasKnownOffset ? 0 : Self.maxOffset
170	        return (span.start.addingTimeInterval(-margin), span.end.addingTimeInterval(margin))
171	    }
172	
173	    /// The widest real UTC offset, used only to widen an uncertain span.
174	    static let maxOffset: TimeInterval = 14 * 3600
175	
176	    /// Whether this value's instant is pinned to a real point on the timeline.
177	    ///
178	    /// True when the stored text carries its own offset (`Z` or `±hh:mm`) or a
179	    /// zone was recorded alongside it. False for a bare label such as
180	    /// `"2019-03"` or `"2019-03-14T08:10"` with no recorded zone — those name a
181	    /// wall-clock reading whose instant depends on where the person was.
182	    public var hasKnownOffset: Bool {
183	        guard isKnown, Self.shapeMatches(text, precision) else { return false }
184	        if Self.explicitOffset(text) != nil { return true }
185	        return zone.offsetMinutes.map { abs($0) <= 14 * 60 } ?? false
186	    }
187	
188	    static func explicitOffset(_ text: String) -> Int? {
189	        guard text.contains("T") else { return nil }
190	        if text.hasSuffix("Z") || text.hasSuffix("z") { return 0 }
191	        guard let range = text.range(of: #"[+-][0-9]{2}:?[0-9]{2}$"#, options: .regularExpression) else { return nil }
