199	        guard explicitOffset(text) != nil else { return text }
200	        if text.hasSuffix("Z") || text.hasSuffix("z") { return String(text.dropLast()) }
201	        let suffixLength = text.suffix(6).contains(":") ? 6 : 5
202	        return String(text.dropLast(suffixLength))
203	    }
